/**
 * Android release signing from the environment.
 *
 * `app/android/` is generated by `expo prebuild`, so a signing config cannot live
 * in the checked-in project: this plugin appends it to the generated
 * `android/app/build.gradle`. The release build is signed with the maintainer's
 * key only when KERYX_KEYSTORE_FILE (absolute path), KERYX_KEYSTORE_PASSWORD,
 * KERYX_KEY_ALIAS and KERYX_KEY_PASSWORD are set — CI sets them from the
 * repository secrets, a local release build sources
 * `../keryx-release-keys/credentials.env`. Without them `release` keeps the
 * debug key, so a plain local build needs no credentials.
 */
const { withAppBuildGradle } = require('@expo/config-plugins');

const MARKER = '// Keryx release signing';

const BLOCK = `

${MARKER} (app/plugins/withAndroidReleaseSigning.js)
def keryxKeystore = System.getenv('KERYX_KEYSTORE_FILE')
if (keryxKeystore) {
    android {
        signingConfigs {
            release {
                storeFile file(keryxKeystore)
                storePassword System.getenv('KERYX_KEYSTORE_PASSWORD')
                keyAlias System.getenv('KERYX_KEY_ALIAS')
                keyPassword System.getenv('KERYX_KEY_PASSWORD')
            }
        }
        buildTypes {
            release {
                signingConfig signingConfigs.release
            }
        }
    }
}
`;

module.exports = function withAndroidReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (!cfg.modResults.contents.includes(MARKER)) {
      cfg.modResults.contents += BLOCK;
    }
    return cfg;
  });
};
